// rankings-loader.js
// This file loads ranking data from Subsystem A (JSON file)

async function loadRankingsFromFile() {
    console.log('📊 Loading rankings from Subsystem A...');
    
    try {
        // Try to load the JSON file generated by Subsystem A
        const response = await fetch('rankings_data.json');
        
        if (!response.ok) {
            throw new Error(`Could not find rankings_data.json (Status: ${response.status})`);
        }
        
        const data = await response.json();
        console.log('✅ Successfully loaded data from Subsystem A!');
        console.log('📅 Generated on:', data.generated);
        console.log('👥 Total players:', data.totalPlayers);
        
        // Update the rankings display
        updateRankingsWithData(data);
        
        // Show success message
        showIntegrationStatus('success', 'Connected to Subsystem A - Data loaded successfully!');
        
    } catch (error) {
        console.error('❌ Failed to load from Subsystem A:', error);
        showIntegrationStatus('error', 'Subsystem A not connected - Using fallback data');
        
        // Use fallback data if file doesn't exist
        useFallbackData();
    }
}

function updateRankingsWithData(data) {
    // Update Most Active tab
    if (data.categories && data.categories.active) {
        updateRankingTab('active', data.categories.active);
    }
    
    // Update High Score tab
    if (data.categories && data.categories.highscore) {
        updateRankingTab('highscore', data.categories.highscore);
    }
    
    // Update Box Jumps tab
    if (data.categories && data.categories.boxjumps) {
        updateRankingTab('boxjumps', data.categories.boxjumps);
    }
}

function updateRankingTab(tabType, players) {
    // Find the tab container
    const container = document.getElementById('rankings-container');
    if (!container) return;
    
    // Check if this tab is currently active
    const activeTab = document.querySelector('.ranking-tab.active');
    const currentTabType = activeTab ? activeTab.getAttribute('data-type') : 'active';
    
    // Only update if this is the active tab
    if (currentTabType === tabType) {
        displayRankings(players, tabType);
    }
}

function showIntegrationStatus(status, message) {
    // Create or update status indicator
    let statusDiv = document.getElementById('integration-status');
    
    if (!statusDiv) {
        // Create status div if it doesn't exist
        statusDiv = document.createElement('div');
        statusDiv.id = 'integration-status';
        statusDiv.style.margin = '10px 0';
        statusDiv.style.padding = '10px';
        statusDiv.style.borderRadius = '5px';
        statusDiv.style.fontWeight = 'bold';
        
        // Insert after rankings tabs
        const rankingsSection = document.getElementById('rankings');
        if (rankingsSection) {
            rankingsSection.insertBefore(statusDiv, document.getElementById('rankings-container'));
        }
    }
    
    statusDiv.style.backgroundColor = status === 'success' ? 'rgba(40, 167, 69, 0.2)' : 'rgba(220, 53, 69, 0.2)';
    statusDiv.style.border = status === 'success' ? '2px solid #28a745' : '2px solid #dc3545';
    statusDiv.style.color = status === 'success' ? '#28a745' : '#dc3545';
    statusDiv.innerHTML = `
        <div style="display: flex; align-items: center; gap: 10px;">
            <i class="bi ${status === 'success' ? 'bi-check-circle-fill' : 'bi-exclamation-triangle-fill'}"></i>
            <span>${message}</span>
        </div>
    `;
}

