// Override the existing displayRankings function or add this one
function displayRankings(rankings, type) {
    const container = document.getElementById('rankings-container');
    if (!container) return;
    
    let html = '';
    
    rankings.forEach((player, index) => {
        let cardClass = 'ranking-card';
        if (index === 0) cardClass += ' gold';
        else if (index === 1) cardClass += ' silver';
        else if (index === 2) cardClass += ' bronze';
        
        let scoreLabel = '';
        switch(type) {
            case 'active': scoreLabel = 'Active Time'; break;
            case 'highscore': scoreLabel = 'High Score'; break;
            case 'boxjumps': scoreLabel = 'Box Jumps'; break;
        }
        
        html += `
            <div class="${cardClass} d-flex align-items-center">
                <div class="ranking-position">${player.position}</div>
                <div class="ranking-avatar">
                    <img src="/images/src1.png" alt="${player.name}" title="${player.name}">
                </div>
                <div class="ranking-info">
                    <div class="ranking-name">${player.name}</div>
                    <div class="ranking-score">${scoreLabel}: ${player.score}</div>
                </div>
                <div class="ranking-badge">${player.badge}</div>
            </div>
        `;
    });
    
    container.innerHTML = html;
}

// Initialize when page loads
document.addEventListener('DOMContentLoaded', function() {
    // Try to load from Subsystem A
    loadRankingsFromFile();
    
    // Override the tab click handlers to refresh data
    setupTabHandlers();
});

function setupTabHandlers() {
    document.querySelectorAll('.ranking-tab').forEach(tab => {
        tab.addEventListener('click', function() {
            // Try to reload data when tab changes
            loadRankingsFromFile();
        });
    });
}